alter type public.sale_status add value if not exists 'cancelled';
alter table public.cash_movements drop constraint cash_movements_sale_reference;
alter table public.cash_movements drop constraint cash_movements_sale_id_key;
alter table public.cash_movements add constraint cash_movements_sale_reference check ((movement_type='sale_cash' and sale_id is not null) or (movement_type='withdrawal'));
create table public.sale_cancellations(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),sale_id uuid not null unique references public.sales(id),cash_session_id uuid not null,reason text not null check(char_length(btrim(reason)) between 3 and 300),request_id uuid not null,requested_by uuid not null references auth.users(id),authorized_by uuid not null references auth.users(id),created_at timestamptz not null default now(),constraint sale_cancellations_request_unique unique(business_id,request_id),constraint sale_cancellations_session_business foreign key(cash_session_id,business_id) references public.cash_register_sessions(id,business_id));
alter table public.sale_cancellations enable row level security; create policy "owners or requesters read sale cancellations" on public.sale_cancellations for select to authenticated using(public.is_business_owner(business_id) or requested_by=auth.uid());
create function public.cancel_sale(p_business_id uuid,p_sale_id uuid,p_cash_session_id uuid,p_reason text,p_request_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare cancellation_id uuid; sale_row public.sales%rowtype; session_status public.cash_session_status; line record; payment public.sale_payments%rowtype; begin if auth.uid() is null or not public.is_business_owner(p_business_id) then raise exception 'Solo el dueño puede cancelar ventas confirmadas.'; end if; select id into cancellation_id from public.sale_cancellations where business_id=p_business_id and request_id=p_request_id; if cancellation_id is not null then return cancellation_id; end if; select * into sale_row from public.sales where id=p_sale_id and business_id=p_business_id for update; if not found or sale_row.status<>'confirmed' then raise exception 'La venta no puede cancelarse.'; end if; select status into session_status from public.cash_register_sessions where id=p_cash_session_id and business_id=p_business_id for update; if session_status<>'open' then raise exception 'La cancelación requiere una caja abierta para registrar el movimiento compensatorio.'; end if; select * into payment from public.sale_payments where sale_id=p_sale_id; insert into public.sale_cancellations(business_id,sale_id,cash_session_id,reason,request_id,requested_by,authorized_by) values(p_business_id,p_sale_id,p_cash_session_id,btrim(p_reason),p_request_id,sale_row.sold_by,auth.uid()) returning id into cancellation_id; for line in select * from public.sale_lines where sale_id=p_sale_id loop insert into public.inventory_movements(business_id,variant_id,movement_type,inventory_state,quantity_delta,source_type,source_id,occurred_at,created_by) values(p_business_id,line.variant_id,'adjustment','available',line.quantity,'sale_cancellation_line',line.id,now(),auth.uid()); end loop; if payment.payment_method='cash' then insert into public.cash_movements(business_id,cash_session_id,sale_id,movement_type,amount,created_by) values(p_business_id,p_cash_session_id,p_sale_id,'withdrawal',-payment.amount,auth.uid()); end if; update public.sales set status='cancelled' where id=p_sale_id; insert into public.audit_events(business_id,actor_user_id,event_type,entity_type,entity_id,data) values(p_business_id,auth.uid(),'sale.cancelled','sale',p_sale_id,jsonb_build_object('reason',btrim(p_reason),'cancellation_id',cancellation_id)); return cancellation_id; end; $$;
revoke all on function public.cancel_sale(uuid,uuid,uuid,text,uuid) from public; grant execute on function public.cancel_sale(uuid,uuid,uuid,text,uuid) to authenticated;
